// GakumasPassportServiceServer is the server API for GakumasPassportService service.
// All implementations must embed UnimplementedGakumasPassportServiceServer
// for forward compatibility.
//
// 学マス 用户通行证的游戏空间：玩家只能查看与操作自己绑定的游戏账号（pid 由 Momoko 按绑定决定）。
// 只注册在用户通行证 server 上，请求与响应都在本文件定义，不引用管理端（gm.proto）的消息；共用的只有游戏数据（types.proto）。
// 自助操作按管理端设置的规则执行（开放、每日次数、间隔、审批）；高风险操作在开启两步验证时需要 totp_code。
type GakumasPassportServiceServer interface {
	// 游戏与已配置的玩法（不含服务端与资源版本）
	GetGame(context.Context, *MyRequest) (*PlayerGame, error)
	// 我的玩家条目、概览与登录次数
	GetMyPlayer(context.Context, *MyRequest) (*PlayerDetail, error)
	ListMyIdolCards(context.Context, *MyIdolCardsRequest) (*IdolCardPage, error)
	ListMySupportCards(context.Context, *MySupportCardsRequest) (*SupportCardPage, error)
	ListMyGifts(context.Context, *MyGiftsRequest) (*GiftPage, error)
	ListMyGashaDraws(context.Context, *MyGashaDrawsRequest) (*GashaDrawPage, error)
	// 我的记忆（produced 只保留培育结果，即培育记录）
	ListMyMemories(context.Context, *MyMemoriesRequest) (*MemoryPage, error)
	// 一条记忆的详情与培育记录
	GetMyMemory(context.Context, *MyMemoryRequest) (*MemoryDetail, error)
	// 记忆照片（记忆或培育记录编成记忆的 image_path；游戏里玩家都能看到记忆照片）
	GetMemoryPhoto(context.Context, *MyMemoryPhotoRequest) (*MemoryPhoto, error)
	// 设为援助（资料展示并出借）的记忆，与游戏内的资料设置相同
	SetMyRentalMemory(context.Context, *MyRentalMemoryRequest) (*RentalChange, error)
	// 设为援助（资料展示并出借）的支援卡，与游戏内的资料设置相同
	SetMyRentalSupportCard(context.Context, *MyRentalSupportCardRequest) (*RentalChange, error)
	// 我的资料名片的图片（没有图片时 404 MEISHI_IMAGE_NOT_FOUND）
	GetMyMeishiImage(context.Context, *MyRequest) (*MeishiImage, error)
	GetMyPvp(context.Context, *MyRequest) (*PlayerPvp, error)
	GetMySeminar(context.Context, *MyRequest) (*PlayerSeminar, error)
	// 现在开放的卡池
	ListOngoingGashas(context.Context, *MyRequest) (*GashaEntryPage, error)
	// 目录（名称与素材 ID）
	ListCurrencies(context.Context, *MyCatalogRequest) (*CurrencyPage, error)
	ListItemCatalog(context.Context, *MyItemCatalogRequest) (*ItemEntryPage, error)
	ListIdolCardSkins(context.Context, *MyIdolCardSkinCatalogRequest) (*IdolCardSkinPage, error)
	ListSupportCardCatalog(context.Context, *MySupportCardCatalogRequest) (*SupportCardEntryPage, error)
	ListCharacters(context.Context, *MyCatalogRequest) (*CharacterPage, error)
	ListCostumes(context.Context, *MyCostumeCatalogRequest) (*CostumePage, error)
	ListCostumeHeads(context.Context, *MyCostumeCatalogRequest) (*CostumePage, error)
	ListMusic(context.Context, *MyCatalogRequest) (*MusicPage, error)
	ListProduceCatalog(context.Context, *MyProduceCatalogRequest) (*ProduceEntryPage, error)
	ListSeminars(context.Context, *MyCatalogRequest) (*SeminarEntryPage, error)
	ListProduceCards(context.Context, *MyCatalogRequest) (*ProduceCardEntryPage, error)
	ListProduceItems(context.Context, *MyCatalogRequest) (*ProduceItemEntryPage, error)
	ListMemoryAbilities(context.Context, *MyCatalogRequest) (*MemoryAbilityPage, error)
	// 自助操作（目标为我绑定的游戏账号）
	RefillMyActionPoint(context.Context, *SelfServiceRequest) (*MyChangesResponse, error)
	GrantMyIdolCards(context.Context, *SelfServiceGrantRequest) (*MyIdolCardGrantResponse, error)
	GrantMySupportCards(context.Context, *SelfServiceGrantRequest) (*MySupportCardGrantResponse, error)
	KickMe(context.Context, *SelfServiceRequest) (*MyKickResponse, error)
	RenameMe(context.Context, *SelfServiceRenameRequest) (*MyRenameResponse, error)
	ResetMyPvpDaily(context.Context, *SelfServiceRequest) (*MyChangesResponse, error)
	ExportMyArchive(context.Context, *SelfServiceRequest) (*MyArchiveExportResponse, error)
	SendMyGift(context.Context, *SelfServiceGiftRequest) (*MyGiftSendResponse, error)
	RevokeMyGifts(context.Context, *SelfServiceGiftRevokeRequest) (*MyGiftRevokeResponse, error)
	AdjustMyJewel(context.Context, *SelfServiceJewelRequest) (*MyChangesResponse, error)
	AdjustMyItem(context.Context, *SelfServiceItemRequest) (*MyChangesResponse, error)
	AddMyExp(context.Context, *SelfServiceExpRequest) (*MyChangesResponse, error)
	BanMe(context.Context, *SelfServiceBanRequest) (*MyBanResponse, error)
	UnbanMe(context.Context, *SelfServiceRequest) (*MyBanResponse, error)
	SetMyPassword(context.Context, *SelfServicePasswordRequest) (*MyPasswordResponse, error)
	SetMyPvpRate(context.Context, *SelfServiceRateRequest) (*MyChangesResponse, error)
	ClearMySeminar(context.Context, *SelfServiceRequest) (*MySeminarClearResponse, error)
	ResetMySeminar(context.Context, *SelfServiceRequest) (*MySeminarResetResponse, error)
	mustEmbedUnimplementedGakumasPassportServiceServer()
}

